import os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); HERE = HERE[:-5] if HERE.endswith(("/W_zh", "/W_en")) else HERE; SK = os.environ.get("COURSE_SKILLS") or (os.path.join(os.path.abspath(os.environ["COURSE_REPO"]), ".agents", "skills") if os.environ.get("COURSE_REPO") else os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..")))
for p in ("view-from-text-v3/tools", "view-from-text-v2/tools", "view-from-text-v2/examples"): sys.path.insert(0, os.path.join(SK, p))
sys.path.insert(0, HERE)
import kp06_pages as KP
from htmlkit import native
JD = os.path.join(HERE, "out")
UNIT_ZH, UNIT_EN = "從階梯到反向傳播的梯度", "Backprop slope"
TITLE_ZH = "圖型識別 第四章 KP06：從階梯到反向傳播的梯度（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP06: from the step to the backpropagation gradient (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp06 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 10 頁，所有數字皆由程式計算。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp06 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 10 pages; every number is computed by program."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp06_p{n}", f"lec05-kp06-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("sigmoid 與斜率參數 a", "the sigmoid and the slope parameter a"), 2: ("2–2–1 網路的前向傳遞", "the forward pass of the 2–2–1 network"), 3: ("連鎖律", "the chain rule"), 4: ("誤差訊號 δ", "the error signal δ"), 5: ("隱藏層的 δ", "the δ of the hidden layer"), 6: ("九個權重的更新", "the update of the nine weights"), 7: ("數值核對", "the numerical check"), 8: ("斜率飽和", "slope saturation"), 9: ("小練習", "the exercises")}
PREV = {2: ("階梯函數沒有斜率", "the step having no slope"), 3: ("sigmoid 與斜率參數 a", "the sigmoid and the slope parameter a"), 4: ("2–2–1 網路的前向傳遞", "the forward pass of the 2–2–1 network"), 5: ("連鎖律", "the chain rule"), 6: ("誤差訊號 δ", "the error signal δ"), 7: ("隱藏層的 δ", "the δ of the hidden layer"), 8: ("九個權重的更新", "the update of the nine weights"), 9: ("數值核對", "the numerical check"), 10: ("斜率飽和", "slope saturation")}
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PREV: zh = f"承接上一頁的「{PREV[n][0]}」。" + zh; en = f"Following the previous page on {PREV[n][1]}. " + en
    if n == 10: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("階梯沒有斜率", "Step has no slope"),
    ("階梯函數除了跳躍點斜率處處為 0，跳躍點沒有斜率：拿不到斜率，梯度下降無從下手", "A step has slope 0 everywhere and none at the jump, so gradient descent has no slope to use"),
    ("KP05 的權重是規則直接給的。要讓網路自己學權重，看什麼來調？", "The weights of KP05 were given by rules. To let the network learn them, what should we look at?"),
    ("這是 KP06 的第一頁。先備三件事：斜率（導數），例如 y 等於 x 平方在 x 等於 3 的斜率是 6；偏導數，只讓一個輸入動、其他固定；連鎖律。要讓網路自己學權重，就得看代價對每個權重的斜率，往讓代價變小的方向調。代價函數把預測和目標差多少加總成一個數，本講義用 E 等於二分之一乘 (t 減 o) 的平方；梯度下降就是看代價對每個權重的斜率，往讓代價變小的方向把權重調一點。階梯函數除了跳躍的那一點，斜率都是 0，跳躍的那一點沒有斜率，拿不到斜率，梯度下降無從下手。sigmoid 在 x 等於 0 的切線斜率是 0.25。",
     "This is the first page of KP06. Prerequisites: the slope (derivative), for example the slope of y equal to x squared at x equal to 3 is 6; the partial derivative, moving one input while the others are fixed; and the chain rule. To let the network learn its weights we must look at the slope of the cost with respect to each weight and move in the direction that lowers the cost. The cost function adds up how far the prediction is from the target into one number, here E equal to one half of (t minus o) squared; gradient descent looks at the slope of the cost with respect to each weight and nudges the weight in the direction that lowers the cost. A step function has slope 0 everywhere except at the jump, where it has no slope, so gradient descent has nothing to use. The sigmoid has a tangent slope of 0.25 at x equal to 0."),
    ("Top: the step function with slope 0 on both flat parts and no slope at the jump; the sigmoid with a tangent of slope 0.25 at x = 0; definitions of cost function and gradient descent.",) * 2)
add(2, ("sigmoid 與 a", "Sigmoid and a"),
    ("sigmoid 把階梯磨圓：斜率處處有，但 a 越大，斜率高峰越窄越高（a/4）", "Sigmoid rounds the step: a slope everywhere, but the larger a, the narrower and higher the peak (a/4)"),
    ("階梯函數的斜率處處為 0、跳躍點沒有斜率，梯度下降無從下手。能不能把階梯磨圓，讓每一點都有斜率？", "A step has slope 0 everywhere and none at the jump, so gradient descent has nothing to use. Can we round the step so every point has a slope?"),
    ("這一頁把階梯磨圓成 sigmoid：f(x) 等於 1 除以 (1 加 e 的負 a x 次方)，斜率 f′ 等於 a 乘 f 乘 (1 減 f)，斜率可以用函數值自己算出來。sigmoid 把任何數壓進 0 到 1 之間，a 越大曲線越像階梯。圖中 a 等於 0.7、2、8，斜率的高峰是 a 除以 4：0.175、0.5、2（程式計算）。常見迷思是越接近階梯越好；其實 a 越大，斜率高峰越窄越高，兩側斜率幾乎是 0，反而越難用梯度訓練。離開階梯後，KP03 映射到立方體頂點的幾何說法不再成立，正確分類改由代價函數來扛。",
     "This page rounds the step into a sigmoid: f of x equals 1 over 1 plus e to the minus a x, and the slope f prime equals a times f times 1 minus f, so the slope can be computed from the function value itself. The sigmoid squeezes any number into 0 to 1, and the larger a is, the more the curve looks like a step. The figure uses a equal to 0.7, 2 and 8, and the slope peaks are a over 4: 0.175, 0.5 and 2 (computed by program). The common myth is that the closer to a step the better; in fact the larger a is, the narrower and higher the slope peak and the flatter both sides, so training by gradient gets harder. Away from the step the cube-vertex picture of KP03 no longer holds, and correct classification is carried by the cost function."),
    ("Formulas of the sigmoid and its slope; curves for a = 0.7, 2, 8 against the dashed step; slope peaks 0.175, 0.5 and 2 getting narrower.",) * 2)
add(3, ("前向傳遞", "Forward pass"),
    ("2–2–1 網路前向傳遞：x = (1, 0) 得 y₁ = 0.525、y₂ = 0.450、o = 0.471，E = 0.140", "Forward pass of the 2–2–1 network: x = (1, 0) gives y₁ = 0.525, y₂ = 0.450, o = 0.471 and E = 0.140"),
    ("sigmoid 把階梯磨圓：斜率處處有，但 a 越大，斜率高峰越窄越高。有了斜率，怎麼知道一個權重該調多少？先用小網路走一遍。", "Sigmoid rounds the step: a slope everywhere, but the larger a, the narrower and higher the peak. With slopes available, how much should one weight change? First run a small network."),
    ("這一頁用 2–2–1 網路走前向傳遞：2 個輸入、2 個隱藏單元、1 個輸出單元，每個單元有 3 個權重（偏置、兩個輸入）。輸入 x 等於 (1, 0)，目標 1，a 等於 1，η 等於 0.3。隱藏 1 是 (負 0.10, 0.20, 0.40)，v1 等於 0.10，y1 等於 0.525；隱藏 2 是 (0.10, 負 0.30, 0.20)，v2 等於 負 0.20，y2 等於 0.450；輸出是 (負 0.20, 0.50, 負 0.40)，vo 等於 負 0.118，o 等於 0.471。誤差 e 等於 1 減 0.471 等於 0.529，E 等於二分之一 e 平方等於 0.140（程式計算）。",
     "This page runs the forward pass of a 2-2-1 network: 2 inputs, 2 hidden units and 1 output unit, each unit having 3 weights (a bias and two inputs). The input x is (1, 0), the target is 1, a is 1 and eta is 0.3. Hidden 1 is (minus 0.10, 0.20, 0.40), giving v1 of 0.10 and y1 of 0.525; hidden 2 is (0.10, minus 0.30, 0.20), giving v2 of minus 0.20 and y2 of 0.450; the output is (minus 0.20, 0.50, minus 0.40), giving vo of minus 0.118 and o of 0.471. The error e equals 1 minus 0.471, which is 0.529, and E equals one half of e squared, which is 0.140 (computed by program)."),
    ("The 2-2-1 network with weights and values x=(1,0), y1=0.525, y2=0.450, o=0.471, and the computations v1=0.10, v2=-0.20, vo=-0.118, e=0.529, E=0.140.",) * 2)
add(4, ("連鎖律", "Chain rule"),
    ("連鎖律把 w(o1) 的梯度拆成三段斜率：(−0.529) × 0.249 × 0.525 = −0.069", "The chain rule splits the gradient of w(o1) into three slopes: (−0.529) × 0.249 × 0.525 = −0.069"),
    ("前向傳遞得 o = 0.471、E = 0.140，離目標 1 還差 0.529。每個權重要往哪個方向調、調多少？", "The forward pass gives o = 0.471 and E = 0.140, still 0.529 short of the target 1. Which way and how much should each weight move?"),
    ("這一頁用連鎖律算一個權重的梯度。E 要經過 o、v 才依賴權重 w，所以 ∂E/∂w 等於 ∂E/∂o 乘 ∂o/∂v 乘 ∂v/∂w。以隱藏 1 到輸出的權重 wo1 為例：∂E/∂o 等於 負 (t 減 o) 等於 負 0.529；∂o/∂v 等於 o 乘 (1 減 o) 等於 0.249；∂v/∂w 等於 y1 等於 0.525，也就是這個權重乘的輸入。相乘 負 0.529 乘 0.249 乘 0.525 等於 負 0.069（程式計算）。梯度是負的，表示把 wo1 調大，E 會變小。",
     "This page uses the chain rule to get the gradient of one weight. E depends on the weight w through o and v, so the partial of E with respect to w equals the partial of E with respect to o, times the partial of o with respect to v, times the partial of v with respect to w. Take the weight wo1 from hidden 1 to the output: the first is minus (t minus o), which is minus 0.529; the second is o times 1 minus o, which is 0.249; the third is y1, which is 0.525, the input this weight multiplies. The product minus 0.529 times 0.249 times 0.525 is minus 0.069 (computed by program). The gradient is negative, so raising wo1 lowers E."),
    ("Chain w to v to o to E with three slopes: dv/dw = y1 = 0.525, do/dv = o(1-o) = 0.249, dE/do = -0.529; product -0.069.",) * 2)
add(5, ("誤差訊號 δ", "Error signal δ"),
    ("誤差訊號 δ：梯度是 −δ × 輸入，輸出權重的更新量是 +0.0396、+0.0208、+0.0178", "Error signal δ: the gradient is −δ × input, and the output weights update by +0.0396, +0.0208 and +0.0178"),
    ("連鎖律把 w(o1) 的梯度拆成三段斜率，結果是 −0.069。每個權重都要乘三段，能不能把前兩段合起來只算一次？", "The chain rule split the gradient of w(o1) into three slopes giving −0.069. Must every weight multiply three slopes, or can the first two be combined once?"),
    ("這一頁把前兩段合起來。符號約定：δ 等於 負 ∂E/∂v，也就是誤差乘上斜率；輸出單元 δo 等於 e 乘 f′(vo) 等於 0.529 乘 0.249 等於 0.1319。梯度 ∂E/∂w 等於 負 δ 乘這個權重乘的輸入，例如 負 0.069 等於 負 0.1319 乘 0.525；往下降的方向就是加上 η 乘 δ 乘輸入。三個輸出權重的輸入是 1、0.525、0.450，η 等於 0.3，更新量是 正 0.0396、正 0.0208、正 0.0178，都是正的，因為目標 1 比輸出 0.471 大。來源把 δ 同時寫成 ∂E/∂v 與誤差乘斜率，差一個負號，本講義統一 δ 等於 負 ∂E/∂v。",
     "This page combines the first two slopes. The sign convention: delta equals minus the partial of E with respect to v, the error times the slope; for the output unit delta-o equals e times f prime of vo, which is 0.529 times 0.249, equal to 0.1319. The gradient of E with respect to w equals minus delta times the input of this weight, for example minus 0.069 equals minus 0.1319 times 0.525; the descent direction adds eta times delta times the input. The inputs of the three output weights are 1, 0.525 and 0.450, eta is 0.3, and the updates are plus 0.0396, plus 0.0208 and plus 0.0178, all positive because the target 1 is above the output 0.471. The source writes delta both as the partial of E with respect to v and as error times slope, which differ by a sign; this lecture fixes delta as minus the partial of E with respect to v."),
    ("Delta_o = 0.529 x 0.249 = 0.1319; gradient = -delta x input; bars of the three output updates +0.0396, +0.0208, +0.0178.",) * 2)
add(6, ("隱藏層的 δ", "Hidden δ"),
    ("隱藏單元的 δ 由輸出的 δ 沿權重往回分：δ₁ = 0.0164、δ₂ = −0.0131", "A hidden unit's δ comes back from the output δ along the weights: δ₁ = 0.0164 and δ₂ = −0.0131"),
    ("誤差訊號 δ 讓輸出權重的更新量是 +0.0396、+0.0208、+0.0178。隱藏單元不直接連到目標，它的 δ 怎麼來？", "The error signal δ gives the output weights updates of +0.0396, +0.0208 and +0.0178. A hidden unit is not connected to the target, so where does its δ come from?"),
    ("這一頁是反向傳播：前向算完所有輸出後，從輸出層往回走。隱藏單元 j 只透過連到下一層的權重影響 E，所以 δj 等於 f′(vj) 乘上下一層每個 δk 乘權重 wkj 的總和。j 是隱藏單元的編號，k 是下一層的單元，本例只有輸出單元；wo1 等於 0.50、wo2 等於 負 0.40。δ1 等於 0.2494 乘 0.1319 乘 0.50 等於 0.0164；δ2 等於 0.2475 乘 0.1319 乘 負 0.40 等於 負 0.0131；wo2 是負的，所以 δ2 小於 0（程式計算）。",
     "This page is backpropagation: after the forward pass computes all outputs, walk back from the output layer. A hidden unit j affects E only through the weights to the next layer, so delta j equals f prime of vj times the sum over the next layer of delta k times the weight wkj. The index j numbers the hidden units, k the units of the next layer, here only the output unit; wo1 is 0.50 and wo2 is minus 0.40. Delta 1 equals 0.2494 times 0.1319 times 0.50, which is 0.0164; delta 2 equals 0.2475 times 0.1319 times minus 0.40, which is minus 0.0131; wo2 is negative, so delta 2 is below 0 (computed by program)."),
    ("The network with red dashed arrows back from the output: delta_o = 0.1319, delta_1 = 0.0164, delta_2 = -0.0131 and the formula delta_j = f'(v_j) sum delta_k w(kj).",) * 2)
add(7, ("九個權重更新", "Nine updates"),
    ("九個權重各調一步：輸出 o 從 0.4706 到 0.4857，代價 E 從 0.1401 降到 0.1322", "One step on all nine weights: o goes from 0.4706 to 0.4857 and the cost E from 0.1401 to 0.1322"),
    ("隱藏單元的 δ 由輸出的 δ 沿權重往回分，δ₁ = 0.0164、δ₂ = −0.0131。九個權重的 δ 都有了，一次更新後代價真的下降嗎？", "A hidden unit's δ comes back along the weights: δ₁ = 0.0164 and δ₂ = −0.0131. With all nine δ known, does one update really lower the cost?"),
    ("這一頁把九個權重各調一步，η 等於 0.3。每一列是一個權重：梯度等於 負 δ 乘輸入，更新量等於 η 乘 δ 乘輸入。輸出偏置從 負 0.2000 變 負 0.1604，輸出 w1 從 0.5000 變 0.5208，輸出 w2 從 負 0.4000 變 負 0.3822；隱藏 1 的偏置與 x1 各加 0.0049；隱藏 2 的偏置與 x1 各減 0.0039；x2 等於 0，所以兩個 x2 的權重這次不動。用新權重重新前向：輸出 o 從 0.4706 變 0.4857，E 從 0.1401 降到 0.1322（程式計算）。一步只走一小步，要重複很多步。",
     "This page moves each of the nine weights one step, eta equal to 0.3. Each row is one weight: the gradient equals minus delta times input and the update equals eta times delta times input. The output bias goes from minus 0.2000 to minus 0.1604, the output w1 from 0.5000 to 0.5208 and the output w2 from minus 0.4000 to minus 0.3822; the bias and x1 weight of hidden 1 each gain 0.0049; those of hidden 2 each lose 0.0039; x2 is 0, so the two x2 weights do not move this time. A new forward pass gives output o moving from 0.4706 to 0.4857 and E falling from 0.1401 to 0.1322 (computed by program). One step is small, so many steps must be repeated."),
    ("Table of the nine weights with old value, input, delta, gradient, update and new value; the output moves from 0.4706 to 0.4857 and E falls from 0.1401 to 0.1322.",) * 2)
add(8, ("數值核對", "Numerical check"),
    ("用中心差分核對：九個權重的 −δ × 輸入與差分斜率最大只差約 3.8×10⁻¹¹", "Central-difference check: −δ × input and the finite-difference slope differ by at most about 3.8×10⁻¹¹"),
    ("九個權重各調一步，代價從 0.1401 降到 0.1322。怎麼確定表中的梯度沒有算錯？", "One step on all nine weights lowered the cost from 0.1401 to 0.1322. How can we be sure the gradients in the table are right?"),
    ("這一頁用數值斜率核對。中心差分：把某個權重加減一點點 ε 等於 10 的負 6 次方，看 E 變多少，用 E(w 加 ε) 減 E(w 減 ε) 再除以 2ε。九個權重的 負 δ 乘輸入與差分斜率最大相差約 3.8 乘 10 的負 11 次方（程式重算，用的是上表同一組權重、a 等於 1）。長條是 負 δ 乘輸入，圓點是差分斜率，兩者重合，表示反向傳播的算式正確。這是寫反向傳播程式時最常用的除錯方法。",
     "This page checks the gradients with numerical slopes. The central difference nudges one weight by plus or minus epsilon, equal to 10 to the minus 6, and divides E of w plus epsilon minus E of w minus epsilon by 2 epsilon. Over the nine weights, minus delta times input and the difference slope differ by at most about 3.8 times 10 to the minus 11 (recomputed by program with the same weights as the table and a equal to 1). The bars are minus delta times input and the dots are the difference slopes; they coincide, so the backpropagation formulas are right. This is the most common debugging method when writing a backpropagation program."),
    ("Bars of -delta x input and dots of finite-difference slopes for the nine weights coincide; the largest gap is about 3.8e-11.",) * 2)
add(9, ("斜率飽和", "Slope saturation"),
    ("斜率飽和：x = 3 處 f′ 為 0.068、0.0049、3×10⁻¹⁰，a 太大時權重幾乎不動", "Slope saturation: at x = 3, f′ is 0.068, 0.0049 and 3×10⁻¹⁰; with a too large the weights barely move"),
    ("中心差分核對：−δ × 輸入與差分斜率最大只差約 3.8×10⁻¹¹。a 取大一點讓 sigmoid 更像階梯，梯度還好用嗎？", "The central-difference check: −δ × input and the finite-difference slope differ by at most about 3.8×10⁻¹¹. If a is made larger so the sigmoid looks more like a step, is the gradient still usable?"),
    ("這一頁看斜率飽和。在 x 等於 3，f′(3) 等於 a 乘 f 乘 (1 減 f)：a 等於 0.7 是 0.068，a 等於 2 是 0.0049，a 等於 8 是 3 乘 10 的負 10 次方（程式計算），a 等於 8 比 a 等於 0.7 小了約 8 個數量級。a 太大時，離中心不遠就進入飽和，δ 乘上幾乎是 0 的斜率，權重幾乎不動。所以 a 取中等大小。",
     "This page looks at slope saturation. At x equal to 3, f prime of 3 equals a times f times 1 minus f: 0.068 for a equal to 0.7, 0.0049 for a equal to 2 and 3 times 10 to the minus 10 for a equal to 8 (computed by program), about 8 orders of magnitude below the value at a equal to 0.7. When a is too large the function saturates not far from the centre, delta is multiplied by an almost-zero slope and the weights barely move. So a is chosen at a middle size."),
    ("Log-scale bars of f'(3) for a = 0.7, 2, 8: 0.068, 0.0049 and 3e-10, about 8 orders of magnitude apart.",) * 2)
